package org


fun NWA(snippet: String, against: String, target: String): Pair<String, String> {
    val gap = -2
    val match = 1
    val mismatch = -1
    val sL = snippet.length
    val aL = against.length
    val grid = Array(sL + 1) { IntArray(aL + 1) }

    for (i in 0..aL) {
        grid[0][i] = i * gap
    }

    for (i in 0..sL) {
        grid[i][0] = i * gap
    }

    for (r in 1..sL) {
        for (c in 1..aL) {
            val top = grid[r - 1][c] + gap
            val left = grid[r][c - 1] + gap
            val isMatch: Int
            if (snippet[r - 1] == against[c - 1]) {
                isMatch = match
            }
            else {
                isMatch = mismatch
            }
            val diagonal = grid[r - 1][c - 1] + isMatch
            grid[r][c] = maxOf(diagonal, top, left)
        }
    }

    var r = sL
    var c = aL
    val alignedSnippet = StringBuilder()
    val alignedAgainst = StringBuilder()

    while (r > 0 || c > 0) {
        val score = grid[r][c]
        val isMatch: Int
        if (r > 0 && c > 0 && snippet[r - 1] == against[c - 1]) {
            isMatch = match
        }
        else {
            isMatch = mismatch
        }

        // Basically, look at the previous diagonal and see if
        // the match/mismatch leads to the current score
        if (r > 0 && c > 0 && score == grid[r - 1][c - 1] + isMatch) {
            alignedSnippet.append(snippet[r - 1])
            alignedAgainst.append(against[c - 1])
            r = r - 1
            c = c - 1
        }

        // For this, we pretty much are seeing if our score resulted from a mismatch from the top
        else if (r > 0 && score == grid[r - 1][c] + gap) {
            alignedSnippet.append(snippet[r - 1])
            alignedAgainst.append("-")
            r = r - 1
        }

        // If the other conditions failed, the score must have come from the left
        else {
            alignedSnippet.append("-")
            alignedAgainst.append(against[c - 1])
            c = c - 1
        }
    }

    return Pair(alignedSnippet.reverse().toString(), alignedAgainst.reverse().toString())
}

fun main() {
    val genomeSnippet = ""
    val targetGenome = ""
    val testAgainst = ""

    val expectedSnippet = "--"
    val expectedAgainst = ""

    val result = NWA(genomeSnippet, testAgainst, targetGenome)

    assert(result.first == expectedSnippet)
    assert(result.second == expectedAgainst)

    println("NWA passes unit test!")
}